function checkOwnership() {
    var NULL_UUID = '13814000-1dd2-11b2-8080-808080808080';
    try {
        var user = self.ctx.currentUser;
        if (user && user.authority === 'CUSTOMER_USER') {
            isOwner = true;
            applyOwnerState();
        } else if (user && user.authority === 'TENANT_ADMIN') {
            // Tenant admin can control only if device has no customer assigned
            isOwner = false;
            getTargetEntity(function(entity) {
                if (!entity || !entity.id) { applyOwnerState(); return; }
                var http = getHttpService();
                if (!http) { applyOwnerState(); return; }
                http.get('/api/device/' + entity.id).subscribe(
                    function(resp) {
                        var device = resp.data || resp;
                        var custId = device.customerId && device.customerId.id ? device.customerId.id : null;
                        if (!custId || custId === NULL_UUID) {
                            isOwner = true;
                        }
                        console.log('[v9] Tenant admin device check: customerId=' + custId + ' isOwner=' + isOwner);
                        applyOwnerState();
                    },
                    function() { applyOwnerState(); }
                );
            });
            return;
        } else {
            isOwner = false;
            applyOwnerState();
        }
    } catch(e) {
        isOwner = false;
        applyOwnerState();
    }
}

function applyOwnerState() {
    console.log('[v9] Owner check: authority=' + (self.ctx.currentUser ? self.ctx.currentUser.authority : 'unknown') + ' isOwner=' + isOwner);
    if (!isOwner) {
        var sw = self.ctx.$container.find('#device-switch');
        var toggle = self.ctx.$container.find('.switch-toggle');
        var container = self.ctx.$container.find('.switch-container');
        sw.prop('disabled', true); toggle.addClass('disabled'); container.addClass('disabled');
        self.ctx.$container.find('#durationHours').prop('disabled', true);
        self.ctx.$container.find('#durationMinutes').prop('disabled', true);
    }
}

function getTargetEntity(callback) {
    var datasources = self.ctx.defaultSubscription && self.ctx.defaultSubscription.datasources;
    if (datasources && datasources.length > 0) {
        var ds = datasources[0];
        if (ds.entity && ds.entity.id) { callback(normalizeEntity(ds.entity)); return; }
        if (ds.entityAliasId && self.ctx.aliasController) {
            var aliasInfo = self.ctx.aliasController.getInstantAliasInfo(ds.entityAliasId);
            if (aliasInfo && aliasInfo.currentEntity) { callback(normalizeEntity(aliasInfo.currentEntity)); return; }
            if (aliasInfo && aliasInfo.resolvedEntities && aliasInfo.resolvedEntities.length > 0) { callback(normalizeEntity(aliasInfo.resolvedEntities[0])); return; }
        }
    }
    callback(null);
}

function normalizeEntity(entity) {
    if (!entity) return null;
    var id = entity.id, entityType = entity.entityType;
    if (typeof id === 'object' && id !== null) { entityType = entityType || id.entityType; id = (id.id !== undefined) ? id.id : id; }
    if (!id) return null;
    return { id: String(id), entityType: entityType || 'DEVICE' };
}

function getHttpService() {
    if (self.ctx.$injector) { try { return self.ctx.$injector.get('$http'); } catch (e) {} }
    if (self.ctx.http) return self.ctx.http;
