// ========================================
// HOME TAB: Telemetry Subscription
// ========================================
function setupTelemetrySubscription() {
    if (!self.ctx.defaultSubscription) return;
    if (self.ctx.defaultSubscription.data) processSubscriptionData(self.ctx.defaultSubscription.data);
    if (typeof self.ctx.defaultSubscription.subscribe === 'function') {
        self.ctx.defaultSubscription.subscribe(function(data) { processSubscriptionData(data); });
    }
}

function processSubscriptionData(data) {
    if (!data) return;
    var values = extractTelemetryValues(data);
    if (values && Object.keys(values).length > 0) updateUIWithValues(values);
}

function extractTelemetryValues(data) {
    var values = {};
    var dataKeys = self.ctx.defaultSubscription.dataKeys || [];
    if (Array.isArray(data)) {
        for (var i = 0; i < data.length; i++) {
            var item = data[i];
            if (item && item.dataKey && item.data) {
                var keyName = item.dataKey.name || item.dataKey.label || item.dataKey.key;
                var series = item.data;
                if (Array.isArray(series) && series.length > 0) {
                    var last = series[series.length-1];
                    values[keyName] = Array.isArray(last) ? last[1] : last;
                    if (keyName === 'eventMessage' && Array.isArray(last)) { values['_eventMessageTs'] = last[0]; }
                    if (keyName === 'durationSecs' && Array.isArray(last)) { values['_durationSecsTs'] = last[0]; }
                    if (keyName === 'runType' && Array.isArray(last)) { values['_runTypeTs'] = last[0]; }
                    if (keyName === 'remainingDuration' && Array.isArray(last)) { values['_remainingDurationTs'] = last[0]; }
                    if (keyName === 'relayStatus' && Array.isArray(last)) { values['_relayStatusTs'] = last[0]; }
                    if (keyName === 'resync' && Array.isArray(last)) { values['_resyncTs'] = last[0]; }
                    if (keyName === 'vsmrR' && Array.isArray(last)) { values['_vsmrRTs'] = last[0]; }
                    if (keyName === 'vsmrFlags' && Array.isArray(last)) { values['_vsmrFlagsTs'] = last[0]; }
                }
            }
        }
    } else if (data.data && Array.isArray(data.data)) {
        for (var j = 0; j < dataKeys.length && j < data.data.length; j++) {
            var kn = dataKeys[j].name || dataKeys[j].label || dataKeys[j]._id;
            var s = data.data[j];
            if (Array.isArray(s) && s.length > 0) { var l = s[s.length-1]; values[kn] = Array.isArray(l) ? l[1] : l; }
        }
    }
    return Object.keys(values).length > 0 ? values : null;
}

function updateUIWithValues(values) {
    if (values.voltage !== undefined) self.ctx.$container.find('#voltage-value').text((parseFloat(values.voltage)||0).toFixed(2));
    if (values.current !== undefined) self.ctx.$container.find('#current-value').text((parseFloat(values.current)||0).toFixed(3));

    // A relayStatus datapoint sharing its ts with a resync datapoint came from a
    // replayed log row (current state stamped on a historical entry) - ignore it.
    var relayFromResync = values._relayStatusTs !== undefined && values._resyncTs !== undefined && values._relayStatusTs === values._resyncTs;
    if (values.relayStatus !== undefined && !relayFromResync) {
        var isOn = (values.relayStatus === true || values.relayStatus === 'true' || values.relayStatus === 1 || values.relayStatus === '1' || values.relayStatus === 'ON');
        deviceIsOn = isOn;
        if (values.runType !== undefined) lastRunType = String(values.runType);
        var sw = self.ctx.$container.find('#device-switch');
        if (waitingForConfirmation && isOn === expectedRelayState) { clearConfirmationTimers(); hideBanner(); waitingForConfirmation = false; expectedRelayState = null; }
        sw.off('change'); sw.prop('checked', isOn); sw.on('change', function() { handleSwitchChange($(this).prop('checked')); });
        // Mirror firmware: getNextSchedule is recomputed on every start/stop.
        if (values._relayStatusTs !== undefined && values._relayStatusTs !== lastRelaySchRefreshTs) {
            lastRelaySchRefreshTs = values._relayStatusTs;
            refreshNextSchedule();
        }
        // Toggle countdown vs duration inputs
        if (isOn) {
            self.ctx.$container.find('#durationInputSection').hide();
            // Countdown end-time, anchored at the source datapoint's OWN ts so
            // a stale value lands in the past and is naturally ignored.
            // durationSecs (new firmware) is authoritative; remainingDuration
            // is the old-firmware periodic stream, consulted only when
            // durationSecs has never been published by this device. values<=0
            // (stop/informational events) are skipped. OFF is signalled by
            // relayStatus, which hides the countdown below.
            var end = 0;
            if (values.durationSecs !== undefined && values._durationSecsTs) {
                var durSecs = parseFloat(values.durationSecs)||0;
                if (durSecs > 0) { end = values._durationSecsTs + durSecs*1000; }
            } else if (values.remainingDuration !== undefined && values._remainingDurationTs) {
                var secs = parseInt(values.remainingDuration,10)||0;
                if (secs > 0) { end = values._remainingDurationTs + secs*1000; }
            }
            if (end > Date.now()) countdownEndTime = end;
            // Suppress the countdown when the device is offline (stale/ghost timer)
            // or when the run has no fixed off-time (flow modes L/f).
            var flowRun = (lastRunType === 'L' || lastRunType === 'f');
            if (deviceActive && !flowRun && countdownEndTime && countdownEndTime > Date.now()) startCountdownTicker();
            else { stopCountdownTicker(); self.ctx.$container.find('#countdownDisplay').hide(); }
        } else {
            stopCountdownTicker();
            countdownEndTime = null;
            self.ctx.$container.find('#countdownDisplay').hide();
            self.ctx.$container.find('#durationInputSection').show();
        }
    }

    if (values.power !== undefined) self.ctx.$container.find('#power-value').text((parseFloat(values.power)||0).toFixed(2));
    if (values.energy !== undefined) self.ctx.$container.find('#energy-value').text((parseFloat(values.energy)||0).toFixed(2));
    if (values.cumEnergy !== undefined) self.ctx.$container.find('#cumenergy-value').text((parseFloat(values.cumEnergy)||0).toFixed(2));

    if (values.vsmrR !== undefined) self.ctx.$container.find('#vsmrR-value').text((parseFloat(values.vsmrR)||0).toFixed(1));
    if (values.vsmrY !== undefined) self.ctx.$container.find('#vsmrY-value').text((parseFloat(values.vsmrY)||0).toFixed(1));
    if (values.vsmrB !== undefined) self.ctx.$container.find('#vsmrB-value').text((parseFloat(values.vsmrB)||0).toFixed(1));
    if (values.vsmrFlags !== undefined) { lastVsmrFlags = parseInt(values.vsmrFlags, 10) || 0; lastVsmrFlagsTs = values._vsmrFlagsTs || 0; }
    if (values.vsmrRelay !== undefined) { lastVsmrRelay = (values.vsmrRelay === true || values.vsmrRelay === 'true' || values.vsmrRelay === 1 || values.vsmrRelay === '1'); }
    if (values._vsmrRTs !== undefined) { lastVsmrTs = values._vsmrRTs; updateVsmrFreshness(); updateVsmrStatus(); }

    if (values.active !== undefined) {
        var isActive = (values.active === true || values.active === 'true' || values.active === 1 || values.active === '1');
        deviceActive = isActive;
        updateSwitchDisabledState(isActive);
        var dotEl = self.ctx.$container.find('#onlineDot');
        if (isActive) { dotEl.attr('title', 'Online').removeClass('offline').addClass('online'); }
        else { dotEl.attr('title', 'Offline').removeClass('online').addClass('offline'); stopCountdownTicker(); self.ctx.$container.find('#countdownDisplay').hide(); }
    }

    checkAlerts(values);
    if (values.eventMessage !== undefined) {
        var evtTs = values._eventMessageTs || 0;
        if (evtTs !== lastLoggedEventTs) {
            lastLoggedEventTs = evtTs;
            appendRealtimeLog(values.eventMessage, evtTs);
            refreshNextSchedule();
        }
    }

}

