function handleSwitchChange(isOn) {
    if (!isOwner) { self.ctx.$container.find('#device-switch').prop('checked', !isOn); return; }
    if (!deviceActive) { self.ctx.$container.find('#device-switch').prop('checked', !isOn); return; }
    var method = isOn ? 'turnOn' : 'turnOff';
    var params;
    if (isOn) {
        var h = parseInt(self.ctx.$container.find('#durationHours').val(),10)||0;
        var m = parseInt(self.ctx.$container.find('#durationMinutes').val(),10)||0;
        if (h===0 && m===0) { alert('Set duration before turning ON'); self.ctx.$container.find('#device-switch').prop('checked', false); return; }
        params = {durationHours:h, durationMinutes:m};
    } else { params = false; }

    getTargetEntity(function(entity) {
        if (!entity || !entity.id) { self.ctx.$container.find('#device-switch').prop('checked', !isOn); alert('Device not found'); return; }
        var http = getHttpService();
        if (!http) { self.ctx.$container.find('#device-switch').prop('checked', !isOn); alert('HTTP service unavailable'); return; }
        http.post('/api/rpc/oneway/' + entity.id, {method:method, params:params, timeout:5000}).subscribe(
            function() { startConfirmationTimers(isOn); },
            function() { self.ctx.$container.find('#device-switch').prop('checked', !isOn); alert('Failed to ' + (isOn?'turn on':'turn off') + ' device'); }
        );
        if (!isOn) self.ctx.$container.find('#countdownDisplay').hide(); self.ctx.$container.find('#durationInputSection').show();
    });
}

function startCountdownTicker() {
    renderCountdown();
    if (!countdownTicker) countdownTicker = setInterval(renderCountdown, 1000);
}

function stopCountdownTicker() {
    if (countdownTicker) { clearInterval(countdownTicker); countdownTicker = null; }
}

function renderCountdown() {
    var secs = Math.round((countdownEndTime - Date.now())/1000);
    if (secs <= 0) {
        stopCountdownTicker(); countdownEndTime = null;
        self.ctx.$container.find('#countdownDisplay').hide();
        return;
    }
    updateCountdown(secs);
}

function updateCountdown(secs) {
    var h=Math.floor(secs/3600), m=Math.floor((secs%3600)/60), s=secs%60;
    self.ctx.$container.find('#cdHours').text(pad2(h));
    self.ctx.$container.find('#cdMinutes').text(pad2(m));
    self.ctx.$container.find('#cdSeconds').text(pad2(s));
    self.ctx.$container.find('#countdownDisplay').show();
}

