// Pull the latest runType (event-based telemetry, so it can sit outside the
// subscription's realtime window) directly from the server, then render the
// schedule. Without this, lastRunType can stay null for a run that started
// before the window and Current Schedule would never show.
function renderScheduleFromServer(entity) {
    var http = getHttpService();
    function renderWithSchedule() {
        self.ctx.attributeService.getEntityAttributes(entity, 'CLIENT_SCOPE', ['schedule']).subscribe(function(attrs) {
            if (attrs) for (var i=0;i<attrs.length;i++) { var k=attrs[i].key||attrs[i].attributeKey; if(k==='schedule') displayNextSchedule(attrs[i].value); }
        });
    }
    if (http && entity && entity.id) {
        http.get('/api/plugins/telemetry/DEVICE/'+entity.id+'/values/timeseries?keys=runType').subscribe(
            function(r) { var d=r&&r.data?r.data:r; if (d && d.runType && d.runType[0]) lastRunType = String(d.runType[0].value); renderWithSchedule(); },
            function() { renderWithSchedule(); }
