}

// Shared with the embedded portal (script.js) - keep both copies in sync.
// Returns {current, next}: the active ON window (cyclic: the running cycle)
// and the nearest upcoming one across all enabled schedules.
function computeScheduleInfo(arr) {
    var now = new Date();
    var nowDay = (now.getDay() + 6) % 7; // convert JS Sun=0..Sat=6 to Mon=0..Sun=6, matching stored schedule day indices
    var nowAbs = now.getHours() * 60 + now.getMinutes();
    var dayNames = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
    var current = null;
    var nextText = null;
    var nextMinsAway = Infinity;

    function p2(n) { return String(n).padStart(2, '0'); }
    function to12(mins) {
        mins = ((mins % 1440) + 1440) % 1440;
        var h = Math.floor(mins / 60), m = mins % 60;
        var ampm = h >= 12 ? 'PM' : 'AM';
        var h12 = h % 12; if (h12 === 0) h12 = 12;
        return p2(h12) + ':' + p2(m) + ' ' + ampm;
    }
    function labelFor(dd) {
        if (dd === 0) return 'Today';
        if (dd === 1) return 'Tomorrow';
        if (dd === -1) return 'Yesterday';
        return dayNames[((nowDay + dd) % 7 + 7) % 7];
    }
    // A window is labelled by the day it STARTS (startAbs can be negative for a
    // window that began yesterday and wraps past midnight into now).
    function seg(startAbs, endAbs, cyc) {
        return labelFor(Math.floor(startAbs / 1440)) + ', ' + to12(startAbs) + ' - ' + to12(endAbs) + (cyc ? ' (Cyclic)' : '');
    }
    function candidate(minsAway, text) {
        if (minsAway < nextMinsAway) { nextMinsAway = minsAway; nextText = text; }
    }

    for (var i = 0; i < arr.length; i++) {
        var s = arr[i];
        if (!(s.e === true || s.e === 1 || s.e === '1' || s.e === 'true')) continue;

        var startMins = (parseInt(s['1'],10)||0) * 60 + (parseInt(s['2'],10)||0);
        var endMins = (parseInt(s['3'],10)||0) * 60 + (parseInt(s['4'],10)||0);
        var isCyclic = (s.c === 1 || s.c === true || s.c === '1');
        var isDaily = (s.t === 'D');
        var isWeekly = (s.t === 'W');
        var days = s.d || [];
        var onDur = (parseInt(s['5'],10)||0) * 60 + (parseInt(s['6'],10)||0);
        var offDur = (parseInt(s['7'],10)||0) * 60 + (parseInt(s['8'],10)||0);
        var cycleDur = onDur + offDur;
        // Overnight windows (end <= start, e.g. 15:11 -> 00:00) wrap past midnight.
        var winLen = endMins > startMins ? (endMins - startMins) : (endMins + 1440 - startMins);

        // dd = -1 catches a window that started yesterday and is still running now.
        for (var dd = -1; dd <= 7; dd++) {
            var checkDay = ((nowDay + dd) % 7 + 7) % 7;
            if (!(isDaily || (isWeekly && days.indexOf(checkDay) >= 0))) continue;
            var winStart = dd * 1440 + startMins;
            var winEnd = winStart + winLen;

            if (nowAbs >= winStart && nowAbs < winEnd) {
                /* Inside this window */
                if (isCyclic && cycleDur > 0) {
                    var pos = (nowAbs - winStart) % cycleDur;
                    if (pos < onDur) {
                        /* ON period: this cycle is current, next cycle is next */
                        var onStart = nowAbs - pos;
                        current = seg(onStart, Math.min(onStart + onDur, winEnd), true);
                        var nextOn = onStart + cycleDur;
                        if (nextOn < winEnd) candidate(nextOn - nowAbs, seg(nextOn, Math.min(nextOn + onDur, winEnd), true));
                    } else {
                        /* OFF period: next cycle is the next event */
                        var nextOn2 = nowAbs + (cycleDur - pos);
                        if (nextOn2 < winEnd) candidate(nextOn2 - nowAbs, seg(nextOn2, Math.min(nextOn2 + onDur, winEnd), true));
                    }
                } else if (!isCyclic) {
                    current = seg(winStart, winEnd, false);
                }
            } else if (winStart > nowAbs) {
                var firstEnd = (isCyclic && cycleDur > 0) ? Math.min(winStart + onDur, winEnd) : winEnd;
                candidate(winStart - nowAbs, seg(winStart, firstEnd, isCyclic));
            }
        }
    }
    return { current: current, next: nextText };
}

function displayNextSchedule(scheduleData) {
    var div = self.ctx.$container.find('#next-schedule-display');
    if (!scheduleData) { div.hide(); return; }
    try {
        var sch = typeof scheduleData === 'string' ? JSON.parse(scheduleData) : scheduleData;
        var arr = sch.s || sch;
        if (!Array.isArray(arr)) { div.hide(); return; }
        var info = computeScheduleInfo(arr);
        // Only present a running window as "Current Schedule" when the device is
        // actually ON via a schedule (S/C/R). A manual/button/web start that
        // interrupted the schedule reports a different runType, and its short run
        // would not match the schedule window - hide current, keep next.
        // Show "Current Schedule" only for a schedule-driven run (runType S/C/R).
        // Old devices don't publish runType/durationSecs, so lastRunType stays
        // null and current is hidden - we can't tell a schedule run from a manual
        // one there, so we don't show a possibly-misleading window.
        var showCurrent = deviceIsOn && (lastRunType === 'S' || lastRunType === 'C' || lastRunType === 'R');
        var html = '';
        // Current Schedule display disabled: the running window is fixed at start
        // time, but the schedule can be edited while ON, so a client-computed
        // current window may not match what's actually executing. Revisit later.
        // if (info.current && showCurrent) html += '<div><span class="schedule-label">Current Schedule:</span><span class="schedule-time">' + info.current + '</span></div>';
        if (info.next) html += '<div><span class="schedule-label">Next Schedule:</span><span class="schedule-time">' + info.next + '</span></div>';
        if (html) { div.html(html); div.show(); }
        else { div.hide(); }
    } catch(e) { console.log('[v9] Next schedule error:', e); div.hide(); }
}


function isAlertMessage(s) {
    if (!s) return false;
    var t = String(s).toLowerCase();
    return t.indexOf('alert') >= 0 || t.indexOf('fail') >= 0 || t.indexOf('reject') >= 0 ||
           t.indexOf('leak') >= 0 || t.indexOf('fault') >= 0 || t.indexOf('overload') >= 0 ||
           t.indexOf('overrun') >= 0 || t.indexOf('dry run') >= 0 ||
           t.indexOf('high voltage') >= 0 || t.indexOf('low voltage') >= 0 ||
           t.indexOf('phase') >= 0;
}

function displayRecentLogs(entries) {
    var el=self.ctx.$container.find('#recent-logs-list'); el.empty();
    var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    if (!entries||!entries.length) { el.html('<div class="log-entry log-placeholder">No recent logs</div>'); return; }
    for (var i=0;i<entries.length&&i<10;i++) {
        var ts=entries[i].ts||0, val=entries[i].value||'';
        var datePart='', timePart='';
        if (ts) {
            var dt=new Date(parseInt(ts,10));
            var h=dt.getHours(), ampm=h>=12?'pm':'am';
            h=h%12; if(h===0)h=12;
            datePart=pad2(dt.getDate())+'/'+monthNames[dt.getMonth()];
            timePart=h+':'+pad2(dt.getMinutes())+':'+pad2(dt.getSeconds())+ampm;
        }
        var alertCls = isAlertMessage(val) ? ' log-alert' : '';
        el.append('<div class="log-entry'+alertCls+'"><span class="log-date">'+datePart+'</span><span class="log-time-val">'+timePart+'</span><span class="log-message">'+escapeHtml(String(val))+'</span></div>');
    }
}

function appendRealtimeLog(msg, ts) {
    var el=self.ctx.$container.find('#recent-logs-list'); el.find('.log-placeholder').remove();
    var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var now = ts ? new Date(parseInt(ts,10)) : new Date();
    var h=now.getHours(), ampm=h>=12?'pm':'am'; h=h%12; if(h===0)h=12;
    var datePart=pad2(now.getDate())+'/'+monthNames[now.getMonth()];
    var timePart=h+':'+pad2(now.getMinutes())+':'+pad2(now.getSeconds())+ampm;
    var alertCls = isAlertMessage(msg) ? ' log-alert' : '';
    el.prepend('<div class="log-entry'+alertCls+'"><span class="log-date">'+datePart+'</span><span class="log-time-val">'+timePart+'</span><span class="log-message">'+escapeHtml(String(msg))+'</span></div>');
    var entries=el.find('.log-entry'); if(entries.length>10) entries.slice(10).remove();
}

