// VSMR freshness: bright while the newest vsmrR datapoint is < 10 min old
// (the relay-OFF publish path only sends on drift or its 10-minute heartbeat),
// dull (vsmr-stale) otherwise. Ticker re-checks so the row dims when
// telemetry STOPS arriving (no data callback fires for silence).
function updateVsmrFreshness() {
    var fresh = lastVsmrTs && (Date.now() - lastVsmrTs) <= 600000;
    var els = self.ctx.$container.find('#vsmr-voltages, #vsmr-status');
    if (fresh) els.removeClass('vsmr-stale');
    else els.addClass('vsmr-stale');
}

// VSMR status, mirroring the local portal. vsmrFlags is only published when
// non-zero, so a flags datapoint older than the newest voltage datapoint is a
// leftover from a past fault - treat it as healthy.
function updateVsmrStatus() {
    var st = self.ctx.$container.find('#vsmr-status');
    if (!st.length) return;
    var flags = (lastVsmrFlagsTs && lastVsmrTs && (lastVsmrTs - lastVsmrFlagsTs) < 15000) ? lastVsmrFlags : 0;
    var txt, cls;
    if (flags & 0x07) { txt = 'Phase Failure'; cls = 'vs-fault'; }
    else if (flags & 0x08) { txt = 'Sequence Mismatch'; cls = 'vs-fault'; }
    else if (lastVsmrRelay) { txt = '3 Phase Voltages OK'; cls = 'vs-ok'; }
    else { txt = 'VSMR Relay Off'; cls = 'vs-idle'; }
    st.text(txt).removeClass('vs-ok vs-fault vs-idle').addClass(cls);
}

