    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.data) processSubscriptionData(self.ctx.defaultSubscription.data);
}

self.onDestroy = function() {
    clearConfirmationTimers();
    stopCountdownTicker();
    if (vsmrStaleTicker) { clearInterval(vsmrStaleTicker); vsmrStaleTicker = null; }
    if (nextSchRefreshTimer) { clearTimeout(nextSchRefreshTimer); nextSchRefreshTimer = null; }
    waitingForConfirmation=false; expectedRelayState=null; countdownEndTime=null;
}
